package com.achulkov.evokammer.competition.grader

import com.achulkov.evokammer.core.contract.DstRefinementProposal
import kotlinx.serialization.Serializable

/**
 * A structured evaluation rubric produced by a Grader Group civilisation.
 *
 * The [GradingSheet] is generated by Grader agents (GraderResearcher, GraderBuilder,
 * GraderCritic) working on their own substrate. It defines automated tests, rubric
 * dimensions, weights, failure modes, and comparative pairs for evaluating competing groups.
 *
 * GradingSheets are sealed by the Watchdog at the start of evaluation and revealed
 * simultaneously to all groups after scoring is complete.
 *
 * @param sheetId Unique ID for this sheet (UUID).
 * @param runId The run this sheet evaluates.
 * @param roundIndex The round this sheet applies to.
 * @param graderGroupId ID of the Grader Group that produced this sheet.
 * @param rubricDimensions Weighted dimensions to evaluate against.
 * @param automatedTests Programmatic tests to run against each group's KB export.
 * @param failureModes Known patterns that constitute a failure.
 * @param comparativePairs Pairs of groups to compare head-to-head.
 * @param proposedRefinements DST structural refinement proposals from this grader group.
 * @param sealedAt Epoch ms when the sheet was sealed (no further modifications allowed).
 * @param qualityScore Self-assessed quality score from Meta-Judge (0.0–1.0); null until adjudicated.
 */
@Serializable
data class GradingSheet(
    val sheetId: String,
    val runId: String,
    val roundIndex: Int,
    val graderGroupId: String,
    val rubricDimensions: List<RubricDimension>,
    val automatedTests: List<AutomatedTest>,
    val failureModes: List<FailureMode>,
    val comparativePairs: List<ComparativePair>,
    val proposedRefinements: List<DstRefinementProposal> = emptyList(),
    val sealedAt: Long? = null,
    val qualityScore: Double? = null
) {
    /** True if this sheet has been sealed by the Watchdog. */
    val isSealed: Boolean get() = sealedAt != null

    /** Returns a sealed copy of this sheet with the given timestamp. */
    fun seal(timestampMs: Long): GradingSheet = copy(sealedAt = timestampMs)

    /** Returns a copy with the Meta-Judge quality score applied. */
    fun withQualityScore(score: Double): GradingSheet = copy(qualityScore = score.coerceIn(0.0, 1.0))
}

/**
 * A single rubric dimension with weight and scoring guidance.
 *
 * @param dimensionId The scoring dimension ID this maps to.
 * @param name Human-readable name.
 * @param weight Weight [0.0–1.0]; all weights in a sheet must sum to 1.0.
 * @param scoringGuidance Natural-language guidance for scoring agents.
 * @param maxScore Maximum score achievable on this dimension.
 * @param dstNodeRef Optional deliverable-skeleton node reference that this dimension updates.
 */
@Serializable
data class RubricDimension(
    val dimensionId: String,
    val name: String,
    val weight: Double,
    val scoringGuidance: String,
    val maxScore: Double = 10.0,
    val dstNodeRef: String? = null
)

/**
 * An automated test applied to a group's exported KB snapshot.
 *
 * @param testId Unique test identifier.
 * @param description What this test checks.
 * @param expectedOutputPattern Regex or keyword the KB export must match.
 * @param penaltyOnFailure Score penalty applied when this test fails.
 * @param isMandatory If true, failure triggers a Hard Fail (group is disqualified from round).
 */
@Serializable
data class AutomatedTest(
    val testId: String,
    val description: String,
    val expectedOutputPattern: String,
    val penaltyOnFailure: Double = 1.0,
    val isMandatory: Boolean = false
)

/**
 * A known failure pattern that Grader Critic agents watch for.
 *
 * @param modeId Unique failure mode identifier.
 * @param description Natural-language description of the failure pattern.
 * @param penaltyWeight Additional penalty weight if this mode is detected.
 */
@Serializable
data class FailureMode(
    val modeId: String,
    val description: String,
    val penaltyWeight: Double = 0.5
)

/**
 * A head-to-head comparison pair for relative scoring.
 *
 * @param groupIdA First group in the pair.
 * @param groupIdB Second group in the pair.
 * @param preferredGroupId The group expected to score higher (null = unknown/contested).
 */
@Serializable
data class ComparativePair(
    val groupIdA: String,
    val groupIdB: String,
    val preferredGroupId: String? = null
)
